async function selectTheme(mode){
 if(themeSaving||!['light','dark'].includes(mode)||mode===themeMode())return;
 themeSaving=true;
 document.querySelectorAll('[data-action="set-theme"],[data-action="toggle-theme"]').forEach(el=>el.disabled=true);
 const next=mode;
 try {
  const commit=async()=>{
   if(fatal){toast('资料未成功读取，请重新打开后再试。');return false;}
   const candidate=structuredClone(db);candidate.settings.theme=next;
   try{await VisenseStore.save(candidate);db=candidate;render(false);toast(next==='dark'?'已切换到深色模式':'已切换到浅色模式');return true;}
   catch(error){toast(error.message||'外观设置未保存，请重试。');return false;}
  };
  const pending=saveQueue.then(commit);saveQueue=pending.catch(()=>{});
  const ok=await pending;
  if(ok&&modal?.kind==='appearance'){
   document.querySelectorAll('[data-action="set-theme"]').forEach(el=>{
    const selected=el.dataset.value===next;el.setAttribute('aria-pressed',String(selected));
    $('.appearance-check',el).innerHTML=selected?icon('check'):'';
   });
  }
 } finally {
  themeSaving=false;
  document.querySelectorAll('[data-action="set-theme"],[data-action="toggle-theme"]').forEach(el=>el.disabled=false);
  if(modal?.kind==='appearance')$(`[data-action="set-theme"][data-value="${next}"]`)?.focus({preventScroll:true});
  else $('.theme-toggle')?.focus({preventScroll:true});
 }
}
